        s5 = "typedef _Atomic(_Atomic(_Atomic(int (*)(void)) *) *) t;"
        c5 = self._run_c_to_c(s5)
        self.assertEqual(c5, "typedef int (* _Atomic * _Atomic * _Atomic t)(void);\n")
        self._assert_ctoc_correct(s5)

        self._assert_ctoc_correct(r"""
